example_item.example_item_data:
schema = protobuf.load([modulepath('protobuf'), '/tests/data/sensor_stream.proto']);
records = struct('timestamp_ms', {1, 2, 3});
bytes = protobuf.encode(schema, 'SensorSample', records, 'Delimited', true);
txt = protobuf.tojson(schema, 'SensorSample', bytes, 'Delimited', true, 'NDJSON', true)
back = protobuf.fromjson(schema, 'SensorSample', txt, 'NDJSON', true);
numel(back)
